-- raymondpalacios.tech — initial private-data schema. Run with a privileged migration role.
create extension if not exists pgcrypto;
create table if not exists public.leads(id uuid primary key default gen_random_uuid(),email_normalized text unique not null check(char_length(email_normalized)<=254),name text null check(char_length(name)<=120),company text null check(char_length(company)<=160),language text not null check(language in('en','es')),source text not null check(char_length(source)<=80),privacy_consent_at timestamptz not null,privacy_notice_version text not null,marketing_opt_in boolean not null default false,marketing_opt_in_at timestamptz null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.project_access(id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.leads(id) on delete cascade,project_slug text not null check(char_length(project_slug)<=80),accessed_at timestamptz not null default now(),source_page text null check(char_length(source_page)<=100));
create index if not exists project_access_lead_idx on public.project_access(lead_id);create index if not exists project_access_slug_idx on public.project_access(project_slug);
create table if not exists public.contact_messages(id uuid primary key default gen_random_uuid(),lead_id uuid null references public.leads(id) on delete set null,name text not null,email_normalized text not null,subject text not null,message text not null,language text not null check(language in('en','es')),privacy_consent_at timestamptz not null,privacy_notice_version text not null,status text not null default 'new' check(status in('new','reviewed','closed')),created_at timestamptz not null default now());create index if not exists contact_email_idx on public.contact_messages(email_normalized);
create table if not exists public.privacy_requests(id uuid primary key,email_normalized text not null,requested_action text not null check(requested_action in('export','delete','correct')),status text not null default 'pending_verification',verified_at timestamptz null,created_at timestamptz not null default now(),expires_at timestamptz not null);
create table if not exists public.rate_limits(key_hash text not null,endpoint text not null,window_start timestamptz not null,hits integer not null default 1,primary key(key_hash,endpoint,window_start));
-- Atomic server-side rate limiter. Stores only a one-way HMAC key, never a raw IP address.
create or replace function public.rate_limit_check(p_key text,p_endpoint text,p_limit integer,p_window_seconds integer) returns boolean language plpgsql security definer set search_path=public as $$declare v_window timestamptz;v_hits integer;begin v_window:=to_timestamp(floor(extract(epoch from now())/p_window_seconds)*p_window_seconds);insert into public.rate_limits(key_hash,endpoint,window_start,hits)values(p_key,p_endpoint,v_window,1)on conflict(key_hash,endpoint,window_start)do update set hits=public.rate_limits.hits+1 returning hits into v_hits;delete from public.rate_limits where window_start<now()-interval '2 days';return v_hits<=p_limit;end$$;
-- RLS: no anonymous/authenticated browser role receives table policies. Service role is server-only and bypasses RLS.
alter table public.leads enable row level security;alter table public.project_access enable row level security;alter table public.contact_messages enable row level security;alter table public.privacy_requests enable row level security;alter table public.rate_limits enable row level security;
revoke all on public.leads,public.project_access,public.contact_messages,public.privacy_requests,public.rate_limits from anon,authenticated;revoke all on function public.rate_limit_check(text,text,integer,integer) from public,anon,authenticated;
-- Grant the function to service_role only in Supabase if required by your deployment role configuration.
